from pathlib import Path
import shutil
p=Path(__file__).parent
css='''*{box-sizing:border-box}body{margin:0;background:#F7F4F0;color:#1F1F1F;font:15px/1.6 -apple-system,BlinkMacSystemFont,"Apple SD Gothic Neo",sans-serif}header{background:#fff;border-bottom:1px solid #ECE6F0;padding:16px 24px;display:flex;justify-content:space-between;align-items:center}header b{color:#5F0080;font-size:15px;letter-spacing:1px}header span{font-size:13px;color:#6F6F6F}main{max-width:504px;margin:32px auto;padding:0 16px}h1{font-size:22px;line-height:1.45;margin:8px 0 12px}h2{font-size:17px;margin:0 0 12px}p{margin:0 0 20px;color:#625b6c}.eyebrow{font-size:12px;font-weight:700;color:#5F0080;margin-bottom:8px}.card{background:white;border:1px solid #E8E2ED;border-radius:20px;padding:24px;margin:24px 0}.field{display:block;margin:16px 0;font-size:14px;font-weight:600}.field small{color:#6f6f6f;font-weight:400}input:not([type=checkbox]),select{display:block;width:100%;height:48px;border:1px solid #857E8F;border-radius:12px;background:white;padding:0 14px;margin-top:8px;font:inherit;color:#1f1f1f}button,.button{display:flex;align-items:center;justify-content:center;min-height:48px;width:100%;border-radius:999px;background:#5F0080;border:0;color:white;text-decoration:none;font-family:inherit;font-weight:600;line-height:20px;font-size:15px;cursor:pointer;margin-top:16px;padding:12px 16px}.secondary{color:#5F0080;background:white;border:1px solid #dcd2e5;border-radius:12px}.text{background:transparent;color:#5F0080;text-decoration:underline}.checks label{display:flex;align-items:flex-start;gap:10px;padding:10px 0;font-size:14px}.checks input{width:20px;height:20px;accent-color:#5f0080;flex:none}.checks a{color:inherit}.note{font-size:13px;color:#625b6c;margin-top:12px}.notice{background:#F5EDFC;border-radius:12px;padding:16px;margin:20px 0}.notice p{margin:0}.progress{display:flex;gap:8px;margin:24px 0}.progress i{height:4px;background:#DED5E5;flex:1;border-radius:4px}.progress i.on{background:#5f0080}footer{font-size:12px;color:#6f6f6f;text-align:center;padding:24px 16px}a{color:#5f0080}nav{display:flex;flex-wrap:wrap;gap:8px}nav a{border:1px solid #dcd2e5;border-radius:12px;padding:10px 14px;background:white;text-decoration:none}.before{background:#fafafa}.before .card{border:0;border-radius:16px;box-shadow:0 10px 20px #0002;padding:32px}.before main{max-width:480px}.before h1{text-align:center;font-size:24px}.before .intro{text-align:center}.before input,.before select{border-color:#d4d4d4}.before .disabled{opacity:.5}.list{border-top:1px solid #ECE6F0;padding:16px 0}.list b{display:block}.list span{color:#6f6f6f;font-size:13px}:focus-visible{outline:3px solid #875EB3;outline-offset:3px}@media(min-width:768px){main{padding:0 32px;margin-top:48px;max-width:552px}input:not([type=checkbox]),select,.button,button{min-height:44px;height:auto}input:not([type=checkbox]),select{height:44px}}'''
def field(label,placeholder='',typ='text'):
 return f'<label class="field">{label}<input type="{typ}" placeholder="{placeholder}"></label>'
def btn(label,target,cls=''):
 return f'<a class="button {cls}" href="302-{target}.html">{label}</a>'
def page(key,title,body,before=False):
 html=f'<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title} · SDD-302</title><style>{css}</style><body class="{"before" if before else ""}"><header><b>MIND BREEZE</b><span>{"현재 화면 합성 재현" if before else "화면 제안"}</span></header><main>{body}</main><footer>SDD-302 · 가상 데이터 · {"코드 기반 재구성, 실제 서비스 캡처 아님" if before else "동선 확인용 정적 시안"}<br><a href="302-index.html">시안 목록으로</a></footer></body></html>'
 (p/f'302-{key}.html').write_text(html)
page('before','현재 필수 정보 입력','''<div class="card"><h1>마지막 단계예요!</h1><p class="intro">원활한 서비스 이용을 위해<br>아래 정보를 입력해주세요</p>'''+field('이름','예시 회원')+'''<label class="field">성별<select><option>선택해주세요</option><option>남성</option><option>여성</option><option>기타</option></select></label>'''+field('생년월일','YYYY.MM.DD')+field('휴대전화번호 <small>(선택)</small>','010-0000-0000','tel')+'''<button class="disabled" disabled>시작하기</button></div><p class="note">현재 소스: ClientEssentialsPage. 빈 필드·버튼 비활성 상태를 재현했습니다. 상단 표시는 비교용입니다.</p>''',True)
page('start','회원 가입','''<div class="eyebrow">회원 계정</div><h1>마인드브리즈와 함께해요</h1><p>사용할 계정을 선택해 주세요.<br>이미 계정이 있다면 로그인해 주세요.</p><div class="card">'''+btn('Google로 계속하기','social','secondary')+btn('Apple로 계속하기','social','secondary')+'''<p class="note">Apple은 iOS 앱에서 제공해요.</p>'''+btn('이메일로 가입하기','email')+'''</div><p class="note">코치가 보낸 초대가 있다면 연결 정보를 이어서 확인해요.</p><nav><a href="302-roles.html">코치·기관 가입 안내</a></nav>''')
checks='''<div class="checks"><label><input type="checkbox">[필수] 이용약관 동의 <a href="#terms">보기</a></label><label><input type="checkbox">[필수] 개인정보 처리 동의 <a href="#terms">보기</a></label><label><input type="checkbox">[필수] 민감정보 처리 동의 <a href="#terms">보기</a></label><label><input type="checkbox">[선택] 뇌파 측정 동의</label><label><input type="checkbox">[선택] 연구 활용 동의</label></div>'''
page('social','소셜 가입 정보','''<div class="eyebrow">소셜 가입 · 정보 확인</div><div class="progress"><i class="on"></i><i class="on"></i></div><h1>가입 정보를 확인해 주세요</h1><p>Google 또는 Apple 인증 후 필요한 정보를 확인해요.</p><div class="card">'''+field('이름','소셜에서 제공한 이름')+field('생년월일','YYYY.MM.DD')+'''<p class="note">가입 연령 확인에 사용해요. 이미 입력한 정보는 다시 묻지 않아요.</p>'''+checks+btn('동의하고 가입하기','home')+'''</div><details id="terms"><summary>동의 항목 안내</summary><p>실제 화면에서는 각 동의 전문을 별도로 열어요. 이 시안은 동의 기록을 저장하지 않아요.</p></details>''')
page('email','이메일 가입','''<div class="eyebrow">이메일 가입 · 1 / 2</div><div class="progress"><i class="on"></i><i></i></div><h1>이메일을 인증해 주세요</h1><p>인증 후 가입 정보와 동의를 한 화면에서 확인해요.</p><div class="card">'''+field('이메일','member@example.test','email')+'''<button type="button" onclick="document.getElementById('otp').hidden=false">인증번호 받기</button><div id="otp" hidden>'''+field('인증번호','6자리 숫자')+'''<p class="note" role="status">시안에서는 메일을 발송하지 않아요.</p></div>'''+btn('다음 화면 보기','email-info')+'''</div><p class="note">코치 개인 신청은 이메일 인증 후 신청 정보를 받아요. 기관 도입 문의는 웹에서 이어가요.</p>''')
page('email-info','이메일 가입 정보','''<div class="eyebrow">이메일 가입 · 2 / 2</div><h1>계정 정보를 입력해 주세요</h1><p>프로필은 가입 후 설정에서 추가할 수 있어요.</p><div class="card">'''+field('이름','이름')+field('생년월일','YYYY.MM.DD')+field('비밀번호','영문·숫자·특수문자, 8자 이상','password')+field('비밀번호 확인','','password')+field('코치 코드','6자리 숫자')+'''<p class="note">초대 링크로 왔다면 연결할 코치를 표시하고 코드는 다시 받지 않아요.</p>'''+checks+btn('동의하고 가입하기','home')+'''</div><p class="note">행사 후 제안: 가입 단계 통합과 성별 선택 전환은 서버 계약 검증 후 적용해요.</p>''')
page('profile','선택 프로필','''<div class="eyebrow">프로필 · 선택 입력</div><h1>조금 더 알려주셔도 좋아요</h1><p>지금 입력하지 않아도 홈으로 이동할 수 있어요. 설정에서 언제든 추가할 수 있어요.</p><div class="card"><label class="field">성별 <small>(선택)</small><select><option>선택하지 않음</option><option>남성</option><option>여성</option><option>기타</option></select></label>'''+field('전화번호 <small>(선택)</small>','010-0000-0000','tel')+'''<div class="checks"><label><input id="dismiss" type="checkbox">프로필 입력 안내 다시 보지 않기</label></div><p class="note">다른 기기에서도 이 선택을 유지해요. 설정에서 안내를 다시 켤 수 있어요.</p>'''+'''<button onclick="location.href=document.getElementById('dismiss').checked?'302-hidden.html':'302-home.html'">입력한 정보 저장</button>'''+'''<button class="secondary" onclick="location.href=document.getElementById('dismiss').checked?'302-hidden.html':'302-later.html'">나중에 하기</button></div><p class="note">필수 가입 정보와 동의는 앞 단계에서 확인해요.</p>''')
for key,notice in [('home','계정으로 홈을 이용할 수 있어요.'),('later','프로필은 나중에 입력해도 돼요. 설정에서 이어가세요.'),('hidden','프로필 입력 안내를 숨겼어요. 설정에서 다시 켤 수 있어요.')]:
 page(key,'회원 홈',f'''<div class="eyebrow">회원 홈</div><h1>오늘도 나의 속도로</h1><div class="notice" role="status"><p>{notice}</p></div><div class="card"><h2>내 클래스</h2><div class="list"><b>마음 살피기 클래스</b><span>예시 일정 · 11월 11일 14:00</span></div><button onclick="this.textContent='로그인한 계정으로 참여하는 흐름이에요'">클래스 참여하기</button></div>'''+(btn('선택 프로필 입력 안내 보기','profile','secondary') if key=='home' else '')+btn('설정에서 프로필 보기','settings','secondary')+'''<p class="note">선택 프로필을 묻는 팝업 없이 홈을 사용해요.</p>''')
page('settings','프로필 설정','''<div class="eyebrow">설정 / 내 정보</div><h1>프로필 관리</h1><div class="card"><div class="list"><b>선택 프로필</b><span>성별 · 전화번호 · 소개</span>'''+btn('프로필 입력하기','profile','secondary')+'''</div><div class="checks"><label><input type="checkbox">선택 프로필 안내 받기</label></div><p class="note">직접 켠 경우에만 홈 안내를 다시 받을 수 있어요.</p>'''+btn('설정 저장','home')+'''</div>''')
links=''.join(f'<a href="302-{k}.html">{v}</a>' for k,v in [('before','Before · 현재 필수 정보'),('start','가입 시작'),('social','소셜 가입'),('email','이메일 인증'),('email-info','이메일 정보'),('profile','선택 프로필'),('later','나중에 하기 이후'),('hidden','다시 보지 않기 이후'),('settings','설정에서 다시 입력'),('error','저장 오류와 재시도'),('roles','코치·기관 안내')])
page('index','가입 흐름 비교',f'''<div class="eyebrow">SDD-302 · 검토용</div><h1>가입은 짧게,<br>프로필은 내 속도로</h1><p>로그인 때마다 반복되는 입력을 줄이고 회원 홈의 밝은 화면 스타일로 연결합니다.</p><div class="notice"><b>핵심 제안</b><p>선택 프로필은 홈 진입을 막지 않아요.<br>다시 보지 않기 선택은 계정에 저장해요.</p></div><h2>Before / After와 경로 비교</h2><nav>{links}</nav><div class="card"><h2>단계 제안</h2><p>이메일: 인증 → 가입 정보·동의 → 홈<br>소셜: 인증 → 가입 정보·동의 → 홈</p><p class="note">선택 프로필은 별도 화면으로 비교하며 홈 설정에서 접근하는 것을 기본안으로 합니다. 필수 가입 요건은 유지합니다.</p></div><p class="note">390px·768px 대응. Before는 코드 기반 합성 화면입니다. After는 서버 저장·인증을 수행하지 않는 시안입니다.</p>''')
print('시안 HTML 생성',len(list(p.glob('302-*.html'))))

page('roles','코치·기관 가입 안내', '<div class="eyebrow">가입 유형</div><h1>이용 목적을 선택해 주세요</h1><div class="card"><h2>코치</h2><p>기관 소속이라면 기관 담당자의 초대로 시작해요. 개인 코치는 이메일 인증 후 가입을 신청해 주세요.</p><h2>기관</h2><p>웹 도입 문의에서 기관명·담당자·이메일을 알려 주세요. 지정된 관리자 계정으로 로그인할 수 있어요.</p><p class="note">이 화면은 안내 시안이에요. 신청을 접수하지 않아요.</p></div>')
page('error','다시 시도 안내', '<div class="eyebrow">선택 프로필 / 저장 오류</div><h1>선택을 저장하지 못했어요</h1><p>연결을 확인한 뒤 다시 시도해 주세요.</p><div class="notice" role="alert"><p>다른 기기에는 아직 반영되지 않았어요.</p></div>'+btn('다시 시도하기','profile')+btn('이번에는 홈으로','later','secondary'))
